48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        if (!normalizeNewOwner(owner)) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (cityIsAtCapacity(owner.getCity())) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
115	            return new ResponseEntity<>(HttpStatus.CONFLICT);
116	        }
117	        Optional<Owner> householdMember = findHouseholdMember(owner);
118	        if (householdMember.isPresent()) {
119	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
120	                return new ResponseEntity<>(HttpStatus.CONFLICT);
121	            }
122	            joinHousehold(owner, householdMember.get());
123	        }
124	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
125	        owner.setNamesakeCount(countNamesakes(owner));
126	        owner.setMembershipNumber(membershipNumber(owner));
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
145	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
146	        String email = ownerFieldsDto.getEmail();
147	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
148	        this.clinicService.saveOwner(currentOwner);
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Transactional
154	    @Override
155	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        this.clinicService.deleteOwner(owner);
161	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Pet pet = petMapper.toPet(petFieldsDto);
173	        owner.setId(ownerId);
174	        pet.setOwner(owner);
175	        pet.getType().setName(null);
176	        this.clinicService.savePet(pet);
177	        PetDto petDto = petMapper.toPetDto(pet);
178	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
179	            .buildAndExpand(pet.getId()).toUri());
180	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
186	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
187	        if (currentOwner != null) {
188	            Pet currentPet = this.clinicService.findPetById(petId);
189	            if (currentPet != null) {
190	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
191	                currentPet.setName(petFieldsDto.getName());
192	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
193	                this.clinicService.savePet(currentPet);
194	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
195	            }
196	        }
197	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
203	        HttpHeaders headers = new HttpHeaders();
204	        Visit visit = visitMapper.toVisit(visitFieldsDto);
205	        Pet pet = new Pet();
206	        pet.setId(petId);
207	        visit.setPet(pet);
208	        this.clinicService.saveVisit(visit);
209	        VisitDto visitDto = visitMapper.toVisitDto(visit);
210	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
211	            .buildAndExpand(visit.getId()).toUri());
212	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
213	    }
214	
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner != null) {
221	            Pet pet = owner.getPet(petId);
222	            if (pet != null) {
223	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    /**
230	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
231	     * the canonical form each stored value must take: the address is trimmed,
232	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
233	     * telephone is converted to E.164, any email is lower-cased and a missing
234	     * registration date defaults to today. Field-level rejections are reported here
235	     * rather than inline in {@link #addOwner}, and normalisation runs before any
236	     * household comparison so those comparisons see the canonical values.
237	     *
238	     * @param owner the freshly-mapped owner to normalise
239	     * @return {@code true} if the fields are valid, or {@code false} if the address
240	     *         is blank after normalisation or the telephone cannot form a valid
241	     *         E.164 number, in which case the request must be rejected with
242	     *         {@code 400 Bad Request}
243	     */
244	    private boolean normalizeNewOwner(Owner owner) {
245	        String address = Owner.normalizeAddress(owner.getAddress());
246	        if (address.isEmpty()) {
247	            return false;
248	        }
249	        owner.setAddress(address);
250	        String telephone = toE164(owner.getTelephone());
251	        if (telephone == null) {
252	            return false;
253	        }
254	        owner.setTelephone(telephone);
255	        if (owner.getEmail() != null) {
256	            owner.setEmail(owner.getEmail().toLowerCase());
257	        }
258	        if (owner.getRegistrationDate() == null) {
259	            owner.setRegistrationDate(LocalDate.now());
260	        }
261	        return true;
262	    }
263	
264	    /**
265	     * Find an existing owner that belongs to the same household as the given owner,
266	     * i.e. shares the same last name and address (compared case-insensitively with
267	     * runs of whitespace collapsed to a single space).
268	     *
269	     * @param owner the candidate owner being created
270	     * @return the matching existing owner, or empty if none exists
271	     */
272	    private Optional<Owner> findHouseholdMember(Owner owner) {
273	        return this.clinicService.findAllOwners().stream()
274	            .filter(existing -> existing.sameHouseholdAs(owner))
275	            .findFirst();
276	    }
277	
278	    /**
279	     * Assign the joining owner and an existing household member the same stable
280	     * household identifier. The identifier is derived deterministically from the
281	     * shared household key (last name + address, normalised), so every owner in a
282	     * household resolves to the same value; the existing member is updated when it
283	     * does not already carry it.
284	     *
285	     * @param owner    the owner being created
286	     * @param existing an existing owner in the same household
287	     */
288	    private void joinHousehold(Owner owner, Owner existing) {
289	        String householdId = UUID
290	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
291	        owner.setHouseholdId(householdId);
292	        if (!householdId.equals(existing.getHouseholdId())) {
293	            existing.setHouseholdId(householdId);
294	            this.clinicService.saveOwner(existing);
295	        }
296	    }
297	
298	    /**
299	     * Count the existing owners that share the given owner's first and last name,
300	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
301	     * before the new owner is saved, so the result reflects only owners that
302	     * already existed at creation time.
303	     *
304	     * @param owner the candidate owner being created
305	     * @return the number of existing namesakes
306	     */
307	    private int countNamesakes(Owner owner) {
308	        String firstName = normalizeName(owner.getFirstName());
309	        String lastName = normalizeName(owner.getLastName());
310	        return (int) this.clinicService.findAllOwners().stream()
311	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
312	                && normalizeName(existing.getLastName()).equals(lastName))
313	            .count();
314	    }
315	
316	    private static String normalizeName(String value) {
317	        return value == null ? "" : value.trim().toLowerCase();
318	    }
319	
320	    /**
321	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
322	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
323	     * first three letters of the given last name and NNNN a per-city 4-digit
324	     * zero-padded sequence equal to one more than the number of owners already in
325	     * that city (e.g. {@code SYD-SMI-0007}).
326	     *
327	     * @param city     the owner's city
328	     * @param lastName the owner's last name
329	     * @return the assigned customer code
330	     */
331	    /**
332	     * Determine whether the given city has already reached its owner capacity, i.e.
333	     * it already contains 50 or more existing owners (compared case-insensitively
334	     * with surrounding whitespace trimmed). A new owner may not be created in a city
335	     * that is at capacity.
336	     *
337	     * @param city the candidate owner's city
338	     * @return {@code true} if the city already holds 50 or more owners
339	     */
340	    private boolean cityIsAtCapacity(String city) {
341	        String normalizedCity = normalizeName(city);
342	        long count = this.clinicService.findAllOwners().stream()
343	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
344	            .count();
345	        return count >= 50;
346	    }
347	
348	    private String nextCustomerCode(String city, String lastName) {
349	        String city3 = prefix3(city);
350	        String last3 = prefix3(lastName);
351	        long sequence = this.clinicService.findAllOwners().stream()
352	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
353	            .count() + 1L;
354	        return String.format("%s-%s-%04d", city3, last3, sequence);
355	    }
356	
357	    private static String prefix3(String value) {
358	        String v = value == null ? "" : value;
359	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
360	    }
361	
362	    /**
363	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
364	     * where {@code <customerCode>} is the owner's already-assigned customer code and
365	     * YY is the last two digits of the registration date's year (e.g.
366	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
367	     * have been set.
368	     *
369	     * @param owner the owner being created, with customer code and registration date
370	     *              already assigned
371	     * @return the assigned membership number
372	     */
373	    private String membershipNumber(Owner owner) {
374	        int yy = owner.getRegistrationDate().getYear() % 100;
375	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
376	    }
377	
378	    /**
379	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
380	     * code when present, otherwise assume country code '+61' and drop a single
381	     * leading '0' from the national digits. Spaces, dashes and brackets are
382	     * stripped. The result must contain 8 to 15 digits after the '+'.
383	     *
384	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
385	     *         input cannot form a valid E.164 number.
386	     */
387	    private static String toE164(String raw) {
388	        if (raw == null) {
389	            return null;
390	        }
391	        String cleaned = raw.replaceAll("[\\s()-]", "");
392	        String digits;
393	        if (cleaned.startsWith("+")) {
394	            digits = cleaned.substring(1);
395	        } else {
396	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
397	            digits = "61" + national;
398	        }
399	        if (!digits.matches("\\d{8,15}")) {
400	            return null;
401	        }
402	        return "+" + digits;
403	    }
404	}
