88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    /**
96	     * The canonical region derived from this owner's {@link #city} using the fixed
97	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
98	     * {@code Brisbane -> QLD}), or {@code "UNKNOWN"} when the city is not in the
99	     * table. Derived (not persisted); recomputed from the current city each call.
100	     *
101	     * @return the canonical region string, or {@code "UNKNOWN"}
102	     */
103	    @Transient
104	    public String getLocality() {
