164	    /**
165	     * A stable, normalised key identifying this owner's household (same last name
166	     * and address). The last name is folded case- and whitespace-insensitively and
167	     * the address is reduced to its canonical form exactly as in
168	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
169	     * household.
170	     *
171	     * @return the household key
172	     */
173	    public String householdKey() {
174	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
175	    }
176	
177	    /**
178	     * Whether this owner belongs to the same household as {@code other}: that is,
179	     * they share the same last name and address. The last name is compared
180	     * case-insensitively with runs of whitespace collapsed to a single space (and
181	     * surrounding whitespace trimmed); the address is compared in its canonical
182	     * normalised form (see {@link #normalizeAddress(String)}).
183	     *
184	     * @param other the owner to compare against
185	     * @return {@code true} if both owners share a household
186	     */
187	    public boolean sameHouseholdAs(Owner other) {
188	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
189	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
190	    }
191	
192	    /**
193	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
194	     * trim, collapse internal runs of whitespace to a single space and lower-case.
195	     */
196	    private static String normalize(String value) {
197	        if (value == null) {
198	            return "";
199	        }
200	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
201	    }
202	
203	    /**
204	     * Reduce an address to its canonical stored form: trim and collapse runs of
205	     * whitespace to a single space, upper-case, and expand common abbreviations
206	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
207	     * they appear as whole words. The result is what is stored, returned and used
208	     * for every household comparison; it is idempotent, so re-normalising an
209	     * already-normalised address leaves it unchanged.
210	     *
211	     * @param value the raw address (may be {@code null})
212	     * @return the normalised address, or the empty string if {@code value} is
213	     *         {@code null} or blank
214	     */
215	    public static String normalizeAddress(String value) {
216	        if (value == null) {
217	            return "";
218	        }
219	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
220	        if (collapsed.isEmpty()) {
221	            return "";
222	        }
223	        String[] tokens = collapsed.split(" ");
224	        for (int i = 0; i < tokens.length; i++) {
225	            tokens[i] = switch (tokens[i]) {
226	                case "ST" -> "STREET";
227	                case "RD" -> "ROAD";
228	                case "AVE" -> "AVENUE";
229	                default -> tokens[i];
230	            };
231	        }
232	        return String.join(" ", tokens);
233	    }
